export interface PhotoItem {
  id: string;
  name: string;
  thumbUrl: string;
  previewUrl: string;
  fullUrl: string;
  downloadUrl: string;
  aspectRatio: string;
  caption?: string;
}

export interface SubfolderItem {
  id: string;
  name: string;
  slug: string;
  shortTitle: string;
  photoCount: number;
  coverPhoto: PhotoItem | null;
  photos: PhotoItem[];
}

export interface AlbumItem {
  id: string;
  name: string;
  slug: string;
  shortTitle: string;
  category: string;
  date: string;
  location: string;
  photographer: string;
  description: string;
  driveFolderUrl: string;
  photoCount: number;
  hasSubfolders: boolean;
  subfolderCount: number;
  subfolders?: SubfolderItem[];
  coverPhoto: PhotoItem | null;
  photos: PhotoItem[];
  isDriveConnected: boolean;
  year: number;
  hasLivePhotos: boolean;
}

export interface EventDetails {
  title: string;
  englishTitle: string;
  edition: string;
  status: string;
  theme: string;
  dates: string;
  venue: string;
  location: string;
  organizer: string;
  rootDriveFolderId: string;
  rootDriveUrl: string;
  brandColors: {
    plum: string;
    sunsetSaffron: string;
  };
  totalAlbums: number;
  totalPhotos: number;
  totalPhotosCount: number;
}

